--
-- Name: distance_m(numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.distance_m(lat1 numeric, lng1 numeric, lat2 numeric, lng2 numeric) RETURNS double precision
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT 6371000 * 2 * asin(sqrt(
        power(sin(radians((lat2 - lat1)::float8) / 2), 2) +
        cos(radians(lat1::float8)) * cos(radians(lat2::float8)) *
        power(sin(radians((lng2 - lng1)::float8) / 2), 2)))
$$;


--
-- Name: scargo_amr_token_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scargo_amr_token_audit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE aid BIGINT;
BEGIN
 IF TG_OP = 'INSERT' THEN
  IF NEW.audit_id IS NULL THEN
   INSERT INTO amr_auth_token_audits (key_id, hub_id, client, ip, user_agent, issued_by_account_id, issued_by_user_id,
                                      issued_at, expires_at, revoked, revoked_at, revoked_by, revoke_reason)
   VALUES (NEW.key_id, (SELECT hub_id FROM amr_otp_keys WHERE key_id = NEW.key_id), NEW.client, NEW.ip, NEW.user_agent,
           NEW.issued_by_account_id, NEW.issued_by_user_id, NEW.created_at, NEW.expires_at,
           NEW.revoked, NEW.revoked_at, NEW.revoked_by, NEW.revoke_reason)
   RETURNING audit_id INTO aid;
   NEW.audit_id := aid;
  END IF;
  RETURN NEW;
 END IF;
 -- UPDATE: 폐기 값이 새로 생겼을 때만 (마지막 사용 시각 갱신 등은 옮기지 않음)
 IF NEW.audit_id IS NOT NULL
    AND ((NEW.revoked AND NOT OLD.revoked) OR NEW.revoked_at IS DISTINCT FROM OLD.revoked_at
         OR NEW.revoke_reason IS DISTINCT FROM OLD.revoke_reason OR NEW.revoked_by IS DISTINCT FROM OLD.revoked_by) THEN
  UPDATE amr_auth_token_audits a
     SET revoked = TRUE,
         revoked_at = COALESCE(a.revoked_at, NEW.revoked_at, now()),
         revoked_by = COALESCE(a.revoked_by, NEW.revoked_by),
         revoke_reason = COALESCE(a.revoke_reason, NEW.revoke_reason)
   WHERE a.audit_id = NEW.audit_id AND (a.revoked_at IS NULL OR a.revoked_by IS NULL OR a.revoke_reason IS NULL OR NOT a.revoked);
 END IF;
 RETURN NEW;
END $$;


--
-- Name: scargo_check_account_business_no(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scargo_check_account_business_no() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_biz TEXT;
BEGIN
 IF NEW.user_type = 'CORPORATE_APPROVED' AND NEW.business_no IS NOT NULL THEN
  SELECT business_no INTO v_biz FROM companies WHERE company_id = NEW.company_id FOR SHARE;
  IF v_biz IS DISTINCT FROM NEW.business_no THEN
   RAISE EXCEPTION '기업계정 사업자번호(%)가 소속 업체 사업자번호(%)와 다릅니다', NEW.business_no, v_biz
    USING ERRCODE = '23514';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: scargo_check_account_role(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scargo_check_account_role() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_type TEXT; v_cat TEXT;
BEGIN
 IF TG_TABLE_NAME = 'accounts' THEN
  IF NEW.center_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM logistics_centers WHERE center_id = NEW.center_id AND center_type = 'DISTRIBUTION_CENTER' FOR SHARE) THEN
   RAISE EXCEPTION '지역센터 관제사의 소속 센터는 지역 물류센터(DISTRIBUTION_CENTER)여야 합니다 (center_id=%)', NEW.center_id
    USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.user_type IS DISTINCT FROM OLD.user_type THEN
   IF NEW.user_type <> 'CONTAINER_DRIVER' AND EXISTS (SELECT 1 FROM transport_orders WHERE driver_account_id = NEW.account_id) THEN
    RAISE EXCEPTION '앱 오더에 배차된 기사는 CONTAINER_DRIVER 권한을 유지해야 합니다 (account_id=%)', NEW.account_id
     USING ERRCODE = '23514';
   END IF;
   SELECT vehicle_category INTO v_cat FROM trucks WHERE assigned_account_id = NEW.account_id
    AND vehicle_category IS DISTINCT FROM CASE NEW.user_type WHEN 'CONTAINER_DRIVER' THEN 'CONTAINER_TRUCK'
                                                            WHEN 'LINEHAUL_DRIVER' THEN 'GENERAL_TRUCK' END
    AND NOT (vehicle_category IS NULL AND NEW.user_type IN ('CONTAINER_DRIVER', 'LINEHAUL_DRIVER'))
   LIMIT 1;
   IF FOUND THEN
    RAISE EXCEPTION '배정 차량(%)과 맞지 않는 권한(%)으로 바꿀 수 없습니다. 차량 배정을 먼저 바꾸세요 (account_id=%)',
     coalesce(v_cat, '구분 없음'), NEW.user_type, NEW.account_id USING ERRCODE = '23514';
   END IF;
  END IF;

 ELSIF TG_TABLE_NAME = 'transport_orders' THEN
  IF NEW.driver_account_id IS NOT NULL THEN
   SELECT user_type INTO v_type FROM accounts WHERE account_id = NEW.driver_account_id FOR SHARE;
   IF v_type IS DISTINCT FROM 'CONTAINER_DRIVER' THEN
    RAISE EXCEPTION '앱 오더(항만 → 허브) 배차 기사는 컨테이너 운송기사(CONTAINER_DRIVER)여야 합니다 (account_id=%, 권한=%)',
     NEW.driver_account_id, v_type USING ERRCODE = '23514';
   END IF;
  END IF;

 ELSIF TG_TABLE_NAME = 'trucks' THEN
  IF NEW.assigned_account_id IS NOT NULL THEN
   SELECT user_type INTO v_type FROM accounts WHERE account_id = NEW.assigned_account_id FOR SHARE;
   IF v_type IS DISTINCT FROM (CASE NEW.vehicle_category WHEN 'CONTAINER_TRUCK' THEN 'CONTAINER_DRIVER'
                                                         WHEN 'GENERAL_TRUCK' THEN 'LINEHAUL_DRIVER' END)
      AND NOT (NEW.vehicle_category IS NULL AND v_type IN ('CONTAINER_DRIVER', 'LINEHAUL_DRIVER')) THEN
    RAISE EXCEPTION '차량 구분(%)에 맞는 기사 권한이 아닙니다 (vehicle_no=%, 권한=%). 컨테이너 트랙터 = CONTAINER_DRIVER, 일반 화물차 = LINEHAUL_DRIVER',
     coalesce(NEW.vehicle_category, '구분 없음'), NEW.vehicle_no, v_type USING ERRCODE = '23514';
   END IF;
  END IF;

 ELSIF TG_TABLE_NAME = 'logistics_centers' THEN
  IF NEW.center_type <> 'DISTRIBUTION_CENTER' AND EXISTS (SELECT 1 FROM accounts WHERE center_id = NEW.center_id) THEN
   RAISE EXCEPTION '지역센터 관제사가 소속된 센터는 유형을 바꿀 수 없습니다 (center_id=%)', NEW.center_id
    USING ERRCODE = '23514';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: scargo_check_port_leg_shipment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scargo_check_port_leg_shipment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE leg RECORD;
BEGIN
 IF NEW.assignment_id IS NULL THEN RETURN NEW; END IF;
 SELECT shipment_id,leg_type INTO leg FROM shipment_legs
 WHERE assignment_id=NEW.assignment_id FOR SHARE;
 IF NOT FOUND THEN
  RAISE EXCEPTION '존재하지 않는 운송 구간: %',NEW.assignment_id USING ERRCODE='23503';
 END IF;
 IF leg.leg_type='PORT_TO_HUB' THEN
  IF NEW.shipment_id IS NULL THEN
   NEW.shipment_id := leg.shipment_id;
  ELSIF NEW.shipment_id IS DISTINCT FROM leg.shipment_id THEN
   RAISE EXCEPTION '항만→허브 운송 건 불일치: table=%, assignment_id=%, 입력 shipment_id=%, 구간 shipment_id=%',
    TG_TABLE_NAME,NEW.assignment_id,NEW.shipment_id,leg.shipment_id USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END $$;


