-- Name: accounts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.accounts (
    account_id bigint NOT NULL,
    user_name character varying(30),
    user_id character varying(50) NOT NULL,
    user_pw character varying(255) NOT NULL,
    user_type character varying(30) NOT NULL,
    operating_company_id bigint,
    company_id bigint,
    hub_id bigint,
    center_id bigint,
    phone_num character varying(20),
    business_no character varying(20),
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT chk_accounts_admin_operator CHECK ((((user_type)::text <> 'ADMIN'::text) OR (operating_company_id IS NOT NULL))),
    CONSTRAINT chk_accounts_biz_no_format CHECK (((business_no)::text ~ '^[0-9]{3}-[0-9]{2}-[0-9]{5}$'::text)),
    CONSTRAINT chk_accounts_center_scope CHECK ((((user_type)::text = 'CENTER_OP'::text) = (center_id IS NOT NULL))),
    CONSTRAINT chk_accounts_corporate_company CHECK ((((user_type)::text <> 'CORPORATE_APPROVED'::text) OR (company_id IS NOT NULL))),
    CONSTRAINT chk_accounts_hub_scope CHECK ((((user_type)::text = 'HUB_OP'::text) = (hub_id IS NOT NULL))),
    CONSTRAINT chk_user_type CHECK (((user_type)::text = ANY ((ARRAY['ADMIN'::character varying, 'CONTROL'::character varying, 'HUB_OP'::character varying, 'CENTER_OP'::character varying, 'CONTAINER_DRIVER'::character varying, 'LINEHAUL_DRIVER'::character varying, 'CORPORATE_APPROVED'::character varying, 'GENERAL'::character varying, 'CORPORATE_PENDING'::character varying])::text[])))
);


