--
-- Name: container_inspections; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.container_inspections (
    inspection_id bigint NOT NULL,
    order_id bigint,
    driver_account_id bigint,
    container_no character varying(11),
    items jsonb DEFAULT '{}'::jsonb NOT NULL,
    overall_status character varying(10) DEFAULT 'PENDING'::character varying NOT NULL,
    memo text,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    company_id bigint,
    hub_id bigint,
    created_by_account_id bigint,
    finalized_by_account_id bigint,
    cancelled_by_account_id bigint,
    record_status character varying(20) DEFAULT 'DRAFT'::character varying NOT NULL,
    finalized_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    cancel_reason text,
    previous_inspection_id bigint,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_ci_cancelled CHECK (((((record_status)::text = 'CANCELLED'::text) = (cancelled_at IS NOT NULL)) AND (((record_status)::text <> 'CANCELLED'::text) OR (NULLIF(btrim(cancel_reason), ''::text) IS NOT NULL)))),
    CONSTRAINT chk_ci_finalized CHECK ((((record_status)::text <> 'FINALIZED'::text) OR ((finalized_at IS NOT NULL) AND ((overall_status)::text <> 'PENDING'::text)))),
    CONSTRAINT chk_ci_items CHECK (((jsonb_typeof(items) = 'object'::text) AND (NOT jsonb_path_exists(items, '$.keyvalue()?(@."value".type() != "boolean" || !(@."key" like_regex "^(front_wall|left_side|right_side|floor|roof|doors|undercarriage)$"))'::jsonpath)))),
    CONSTRAINT chk_ci_not_self CHECK (((previous_inspection_id IS NULL) OR (previous_inspection_id <> inspection_id))),
    CONSTRAINT chk_ci_overall_status CHECK (((overall_status)::text = ANY ((ARRAY['PENDING'::character varying, 'PASS'::character varying, 'FAIL'::character varying])::text[]))),
    CONSTRAINT chk_ci_record_status CHECK (((record_status)::text = ANY ((ARRAY['DRAFT'::character varying, 'FINALIZED'::character varying, 'CANCELLED'::character varying])::text[])))
);


--
-- Name: TABLE container_inspections; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.container_inspections IS '컨테이너 점검표 (기사 앱, 7-point 등 항목별 양호 여부)';


--
-- Name: COLUMN container_inspections.overall_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.container_inspections.overall_status IS '판정 (백엔드 계산): PENDING 7개 항목 미완 / PASS 모두 양호 / FAIL 하나라도 불량';


