-- Name: container_seals; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.container_seals (
    seal_id bigint NOT NULL,
    shipment_id bigint NOT NULL,
    container_no character varying(11) NOT NULL,
    seal_no character varying(30) NOT NULL,
    seal_position character varying(30) DEFAULT 'MAIN'::character varying NOT NULL,
    seal_type character varying(20) DEFAULT 'CARRIER'::character varying NOT NULL,
    status character varying(20) DEFAULT 'ACTIVE'::character varying NOT NULL,
    attached_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    attached_by_account_id bigint,
    attached_by_name character varying(100),
    removed_at timestamp with time zone,
    previous_seal_id bigint,
    memo text,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT chk_seals_actor CHECK (((attached_by_account_id IS NOT NULL) OR (NULLIF(btrim((attached_by_name)::text), ''::text) IS NOT NULL))),
    CONSTRAINT chk_seals_not_self CHECK (((previous_seal_id IS NULL) OR (previous_seal_id <> seal_id))),
    CONSTRAINT chk_seals_state_time CHECK (((((status)::text = 'ACTIVE'::text) AND (removed_at IS NULL)) OR (((status)::text = ANY ((ARRAY['REMOVED'::character varying, 'REPLACED'::character varying, 'LOST'::character varying])::text[])) AND (removed_at IS NOT NULL) AND (removed_at >= attached_at)))),
    CONSTRAINT container_seals_seal_no_check CHECK ((((seal_no)::text = btrim((seal_no)::text)) AND (length((seal_no)::text) > 0))),
    CONSTRAINT container_seals_seal_position_check CHECK ((((seal_position)::text = btrim((seal_position)::text)) AND (length((seal_position)::text) > 0))),
    CONSTRAINT container_seals_seal_type_check CHECK (((seal_type)::text = ANY ((ARRAY['CARRIER'::character varying, 'CUSTOMS'::character varying, 'OTHER'::character varying])::text[]))),
    CONSTRAINT container_seals_status_check CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'REMOVED'::character varying, 'REPLACED'::character varying, 'LOST'::character varying])::text[])))
);


