--
-- Name: overload_checks; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.overload_checks (
    check_id bigint NOT NULL,
    vehicle_no character varying(20) NOT NULL,
    container_no character varying(11),
    usage_purpose character varying(50),
    empty_weight_kg integer,
    total_weight_kg integer,
    max_payload_kg integer,
    vgm_kg integer,
    tire_count integer,
    vehicle_axle_count integer,
    axle_count integer,
    axle1_weight integer DEFAULT 0,
    axle2_weight integer DEFAULT 0,
    axle3_weight integer DEFAULT 0,
    axle4_weight integer DEFAULT 0,
    axle5_weight integer DEFAULT 0,
    axle6_weight integer DEFAULT 0,
    axle7_weight integer DEFAULT 0,
    axle8_weight integer DEFAULT 0,
    axle1_wheel_left integer DEFAULT 0,
    axle1_wheel_right integer DEFAULT 0,
    axle2_wheel_left integer DEFAULT 0,
    axle2_wheel_right integer DEFAULT 0,
    axle3_wheel_left integer DEFAULT 0,
    axle3_wheel_right integer DEFAULT 0,
    axle4_wheel_left integer DEFAULT 0,
    axle4_wheel_right integer DEFAULT 0,
    axle5_wheel_left integer DEFAULT 0,
    axle5_wheel_right integer DEFAULT 0,
    axle6_wheel_left integer DEFAULT 0,
    axle6_wheel_right integer DEFAULT 0,
    axle7_wheel_left integer DEFAULT 0,
    axle7_wheel_right integer DEFAULT 0,
    axle8_wheel_left integer DEFAULT 0,
    axle8_wheel_right integer DEFAULT 0,
    is_violation boolean NOT NULL,
    violation_reason text,
    retry_count integer DEFAULT 0 NOT NULL,
    is_passed boolean NOT NULL,
    checked_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    shipment_id bigint,
    assignment_id bigint,
    station_id bigint,
    check_type character varying(20),
    detection_status character varying(20),
    gate_log_id bigint,
    station_code character varying(20),
    trip_passage_id bigint,
    fine_manwon integer DEFAULT 0 NOT NULL,
    is_reoffense boolean DEFAULT false NOT NULL,
    CONSTRAINT chk_overload_axle_count CHECK ((((axle_count IS NULL) OR ((axle_count >= 0) AND (axle_count <= 8))) AND ((vehicle_axle_count IS NULL) OR ((vehicle_axle_count >= 1) AND (vehicle_axle_count <= 8))))),
    CONSTRAINT chk_overload_axle_sum CHECK (((total_weight_kg IS NULL) OR (total_weight_kg = (((((((axle1_weight + axle2_weight) + axle3_weight) + axle4_weight) + axle5_weight) + axle6_weight) + axle7_weight) + axle8_weight)))),
    CONSTRAINT chk_overload_check_type CHECK (((check_type IS NULL) OR ((check_type)::text = ANY ((ARRAY['HIGHWAY'::character varying, 'OTHER'::character varying])::text[])))),
    CONSTRAINT chk_overload_detection_status CHECK (((detection_status IS NULL) OR ((detection_status)::text = ANY ((ARRAY['NORMAL'::character varying, 'SUSPECTED'::character varying, 'CONFIRMED'::character varying])::text[])))),
    CONSTRAINT chk_overload_fine CHECK (((fine_manwon >= 0) AND ((fine_manwon = 0) OR is_violation) AND ((NOT is_reoffense) OR (is_violation AND (fine_manwon = 0))))),
    CONSTRAINT chk_overload_wheel_sum CHECK (((axle1_weight = (axle1_wheel_left + axle1_wheel_right)) AND (axle2_weight = (axle2_wheel_left + axle2_wheel_right)) AND (axle3_weight = (axle3_wheel_left + axle3_wheel_right)) AND (axle4_weight = (axle4_wheel_left + axle4_wheel_right)) AND (axle5_weight = (axle5_wheel_left + axle5_wheel_right)) AND (axle6_weight = (axle6_wheel_left + axle6_wheel_right)) AND (axle7_weight = (axle7_wheel_left + axle7_wheel_right)) AND (axle8_weight = (axle8_wheel_left + axle8_wheel_right))))
);


--
-- Name: COLUMN overload_checks.empty_weight_kg; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.overload_checks.empty_weight_kg IS '차량 공차중량(kg)';


--
-- Name: COLUMN overload_checks.total_weight_kg; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.overload_checks.total_weight_kg IS '계근 총중량(kg) = 차량 공차 + 컨테이너(VGM). 축중 합계와 같아야 함';


--
-- Name: COLUMN overload_checks.max_payload_kg; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.overload_checks.max_payload_kg IS '차량 최대적재량(kg)';


--
-- Name: COLUMN overload_checks.vgm_kg; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.overload_checks.vgm_kg IS '컨테이너 총중량(VGM, kg): 컨테이너 자체 중량 + 적재 화물';


--
-- Name: COLUMN overload_checks.vehicle_axle_count; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.overload_checks.vehicle_axle_count IS '차량 제원상(등록) 차축 수';


