--

CREATE TABLE public.parcels (
    parcel_no character varying(20) NOT NULL,
    item_id bigint NOT NULL,
    hub_id bigint NOT NULL,
    receipt_id bigint,
    region_id bigint,
    category character varying(30),
    size_class character(1),
    handling character varying(20) DEFAULT '일반'::character varying NOT NULL,
    status character varying(20) DEFAULT 'IN_TRUCK'::character varying NOT NULL,
    slot_id bigint,
    dispatch_id bigint,
    inbound_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    stored_at timestamp with time zone,
    outbound_at timestamp with time zone,
    CONSTRAINT chk_parcels_handling CHECK (((handling)::text = ANY ((ARRAY['일반'::character varying, '파손주의'::character varying, '취급주의'::character varying, '냉장'::character varying, '중량물'::character varying])::text[]))),
    CONSTRAINT chk_parcels_size CHECK ((size_class = ANY (ARRAY['S'::bpchar, 'M'::bpchar, 'L'::bpchar]))),
    CONSTRAINT chk_parcels_status CHECK (((status)::text = ANY ((ARRAY['IN_TRUCK'::character varying, 'MOVING'::character varying, 'STORED'::character varying, 'OUTBOUND_READY'::character varying, 'SHIPPED'::character varying, 'SORT_FAILED'::character varying])::text[])))
);


--
-- Name: parcel_details; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.parcel_details AS
 SELECT p.parcel_no,
    p.item_id,
    p.hub_id,
    p.receipt_id,
    p.region_id,
    p.category,
    p.size_class,
    p.handling,
    p.status,
    p.slot_id,
    p.dispatch_id,
    p.inbound_at,
    p.stored_at,
    p.outbound_at,
    i.tracking_no,
    i.barcode,
    i.weight_kg,
    i.item_name,
    i.destination_center_id,
    i.status AS delivery_status
   FROM (public.parcels p
     JOIN public.items i ON ((i.item_id = p.item_id)));


