-- Name: road_structure_references; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.road_structure_references (
    reference_id bigint NOT NULL,
    source_key character varying(64) NOT NULL,
    structure_name text NOT NULL,
    structure_height_m numeric(6,2) NOT NULL,
    latitude numeric(10,7) NOT NULL,
    longitude numeric(10,7) NOT NULL,
    sido character varying(20) NOT NULL,
    sigungu character varying(50) NOT NULL,
    administrative_name character varying(100) NOT NULL,
    source_dataset text NOT NULL,
    source_record_date date,
    boundary_version character varying(20) NOT NULL,
    boundary_source text NOT NULL,
    actual_limit_height_m numeric(6,2),
    is_limit_verified boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT chk_structure_verified_limit CHECK (((NOT is_limit_verified) OR (actual_limit_height_m IS NOT NULL))),
    CONSTRAINT road_structure_references_actual_limit_height_m_check CHECK ((actual_limit_height_m > (0)::numeric)),
    CONSTRAINT road_structure_references_latitude_check CHECK (((latitude >= ('-90'::integer)::numeric) AND (latitude <= (90)::numeric))),
    CONSTRAINT road_structure_references_longitude_check CHECK (((longitude >= ('-180'::integer)::numeric) AND (longitude <= (180)::numeric))),
    CONSTRAINT road_structure_references_sido_check CHECK (((sido)::text = ANY ((ARRAY['서울특별시'::character varying, '인천광역시'::character varying, '경기도'::character varying])::text[]))),
    CONSTRAINT road_structure_references_structure_height_m_check CHECK ((structure_height_m > (0)::numeric))
);


