--
-- Name: seal_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.seal_events (
    event_id bigint NOT NULL,
    seal_id bigint NOT NULL,
    shipment_id bigint NOT NULL,
    order_id bigint,
    event_type character varying(20) NOT NULL,
    expected_seal_no character varying(30) NOT NULL,
    observed_seal_no character varying(30),
    observed_condition character varying(20) DEFAULT 'UNKNOWN'::character varying NOT NULL,
    number_matches boolean GENERATED ALWAYS AS (
CASE
    WHEN (observed_seal_no IS NULL) THEN NULL::boolean
    ELSE ((observed_seal_no)::text = (expected_seal_no)::text)
END) STORED,
    actor_account_id bigint,
    actor_name character varying(100),
    center_id bigint,
    occurred_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    reason text,
    photo_urls jsonb DEFAULT '[]'::jsonb NOT NULL,
    memo text,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT chk_seal_events_actor CHECK (((actor_account_id IS NOT NULL) OR (NULLIF(btrim((actor_name)::text), ''::text) IS NOT NULL))),
    CONSTRAINT chk_seal_events_damaged CHECK ((((event_type)::text <> 'DAMAGED'::text) OR ((observed_condition)::text = 'DAMAGED'::text))),
    CONSTRAINT chk_seal_events_lost CHECK ((((event_type)::text <> 'LOST'::text) OR ((observed_condition)::text = 'MISSING'::text))),
    CONSTRAINT chk_seal_events_missing CHECK ((((observed_condition)::text <> 'MISSING'::text) OR (observed_seal_no IS NULL))),
    CONSTRAINT chk_seal_events_replacement_reason CHECK ((((event_type)::text <> 'REPLACED'::text) OR (NULLIF(btrim(reason), ''::text) IS NOT NULL))),
    CONSTRAINT seal_events_event_type_check CHECK (((event_type)::text = ANY ((ARRAY['ATTACHED'::character varying, 'INSPECTED'::character varying, 'OPENED'::character varying, 'REPLACED'::character varying, 'LOST'::character varying, 'DAMAGED'::character varying])::text[]))),
    CONSTRAINT seal_events_observed_condition_check CHECK (((observed_condition)::text = ANY ((ARRAY['INTACT'::character varying, 'DAMAGED'::character varying, 'MISSING'::character varying, 'UNKNOWN'::character varying])::text[]))),
    CONSTRAINT seal_events_observed_seal_no_check CHECK (((observed_seal_no IS NULL) OR (((observed_seal_no)::text = btrim((observed_seal_no)::text)) AND (length((observed_seal_no)::text) > 0)))),
    CONSTRAINT seal_events_photo_urls_check CHECK ((jsonb_typeof(photo_urls) = 'array'::text))
);


--
-- Name: TABLE seal_events; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.seal_events IS '씰 장착·반복 확인·개봉·교체·분실·훼손 이력. 담당자·위치·시각·번호 관측값을 기록';


--
-- Name: COLUMN seal_events.expected_seal_no; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.seal_events.expected_seal_no IS '해당 씰의 등록 번호를 복사. 복합 FK로 부모 번호와 일치 보장';


--
-- Name: COLUMN seal_events.observed_seal_no; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.seal_events.observed_seal_no IS '현장에서 확인한 번호. 분실/판독 불가이면 NULL';


--
-- Name: COLUMN seal_events.observed_condition; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.seal_events.observed_condition IS '물리 상태 INTACT/DAMAGED/MISSING/UNKNOWN. 번호 불일치는 number_matches=FALSE로 별도 표현';


--
-- Name: COLUMN seal_events.number_matches; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.seal_events.number_matches IS '관측 번호와 등록 번호의 자동 비교. 관측값 NULL이면 NULL(미판정)';


