CREATE TABLE public.shipment_legs (
    assignment_id bigint NOT NULL,
    shipment_id bigint,
    vehicle_no character varying(20) NOT NULL,
    from_center_id bigint NOT NULL,
    to_center_id bigint NOT NULL,
    leg_sequence integer DEFAULT 1 NOT NULL,
    leg_type character varying(30) NOT NULL,
    status character varying(20) DEFAULT 'ASSIGNED'::character varying NOT NULL,
    departed_at timestamp with time zone,
    arrived_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    received_at timestamp with time zone,
    received_by_account_id bigint,
    CONSTRAINT chk_leg_shipment_scope CHECK (((((leg_type)::text = 'PORT_TO_HUB'::text) AND (shipment_id IS NOT NULL)) OR (((leg_type)::text = 'HUB_TO_CENTER'::text) AND (shipment_id IS NULL)) OR ((leg_type)::text = 'OTHER'::text))),
    CONSTRAINT chk_legs_received_by CHECK (((received_by_account_id IS NULL) OR (((status)::text = 'RECEIVED'::text) AND (received_at IS NOT NULL)))),
    CONSTRAINT shipment_legs_check CHECK ((from_center_id <> to_center_id)),
    CONSTRAINT shipment_legs_leg_sequence_check CHECK ((leg_sequence > 0)),
    CONSTRAINT shipment_legs_leg_type_check CHECK (((leg_type)::text = ANY ((ARRAY['PORT_TO_HUB'::character varying, 'HUB_TO_CENTER'::character varying, 'OTHER'::character varying])::text[]))),
    CONSTRAINT shipment_legs_status_check CHECK (((status)::text = ANY ((ARRAY['ASSIGNED'::character varying, 'IN_TRANSIT'::character varying, 'ARRIVED'::character varying, 'RECEIVED'::character varying, 'CANCELED'::character varying])::text[])))
);


--
-- Name: COLUMN shipment_legs.shipment_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.shipment_legs.shipment_id IS '항만→허브는 원본 운송 건 필수. 허브→센터는 여러 원본 운송 건을 함께 운송하므로 NULL. 원본 연결은 물품/작업 이력에서 유지.';


--
