--
-- Name: toll_passages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.toll_passages (
    passage_id bigint NOT NULL,
    tollgate_id bigint NOT NULL,
    recognized_plate_no character varying(20),
    vehicle_no character varying(20),
    assignment_id bigint,
    check_id bigint,
    recognition_status character varying(20) NOT NULL,
    passage_status character varying(20) DEFAULT 'PENDING'::character varying NOT NULL,
    block_reason character varying(30),
    detected_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    passed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    plate_confidence numeric(5,2),
    front_image_url text,
    plate_crop_url text,
    entry_passage_id bigint,
    fare_won integer,
    CONSTRAINT chk_toll_passage_block_reason CHECK (((((block_reason)::text IS DISTINCT FROM 'OCR_FAILED'::text) OR ((recognition_status)::text = 'FAILED'::text)) AND (((block_reason)::text IS DISTINCT FROM 'UNREGISTERED'::text) OR (vehicle_no IS NULL)) AND (((block_reason)::text IS DISTINCT FROM 'OVERLOAD'::text) OR (check_id IS NOT NULL)))),
    CONSTRAINT chk_toll_passage_conf CHECK (((plate_confidence IS NULL) OR ((plate_confidence >= (0)::numeric) AND (plate_confidence <= (100)::numeric)))),
    CONSTRAINT chk_toll_passage_entry_ref CHECK (((entry_passage_id IS NULL) OR (entry_passage_id <> passage_id))),
    CONSTRAINT chk_toll_passage_fare CHECK (((fare_won IS NULL) OR ((fare_won >= 0) AND ((passage_status)::text = 'PASSED'::text)))),
    CONSTRAINT chk_toll_passage_passed_valid CHECK ((((passage_status)::text <> 'PASSED'::text) OR (((recognition_status)::text = 'SUCCESS'::text) AND (vehicle_no IS NOT NULL)))),
    CONSTRAINT chk_toll_passage_result CHECK (((((passage_status)::text = 'PASSED'::text) AND (passed_at IS NOT NULL) AND (block_reason IS NULL)) OR (((passage_status)::text = 'BLOCKED'::text) AND (passed_at IS NULL) AND (block_reason IS NOT NULL)) OR (((passage_status)::text = 'PENDING'::text) AND (passed_at IS NULL) AND (block_reason IS NULL)))),
    CONSTRAINT toll_passages_block_reason_check CHECK (((block_reason)::text = ANY ((ARRAY['OCR_FAILED'::character varying, 'UNREGISTERED'::character varying, 'OVERLOAD'::character varying, 'OTHER'::character varying])::text[]))),
    CONSTRAINT toll_passages_passage_status_check CHECK (((passage_status)::text = ANY ((ARRAY['PENDING'::character varying, 'PASSED'::character varying, 'BLOCKED'::character varying])::text[]))),
    CONSTRAINT toll_passages_recognition_status_check CHECK (((recognition_status)::text = ANY ((ARRAY['SUCCESS'::character varying, 'FAILED'::character varying])::text[])))
);


