    CONSTRAINT chk_tollgates_ppt_ownership CHECK (((ppt_ownership_type IS NULL) OR ((ppt_ownership_type)::text = ANY ((ARRAY['PUBLIC'::character varying, 'PRIVATE'::character varying, 'UNKNOWN'::character varying])::text[])))),
