CREATE TABLE public.transport_orders (
    order_id bigint NOT NULL,
    order_no character varying(30) NOT NULL,
    company_id bigint NOT NULL,
    container_no character varying(11) NOT NULL,
    vehicle_no character varying(20),
    driver_account_id bigint,
    origin_terminal_id bigint NOT NULL,
    dest_hub_id bigint NOT NULL,
    status character varying(20) DEFAULT 'CREATED'::character varying NOT NULL,
    gate_out_log_id bigint,
    overload_check_id bigint,
    load_height_m numeric(4,2),
    vgm_kg integer,
    gross_weight_kg integer,
    precheck jsonb,
    planned_route jsonb,
    planned_distance_km numeric(7,2),
    eta timestamp with time zone,
    assigned_at timestamp with time zone,
    loaded_at timestamp with time zone,
    gate_out_at timestamp with time zone,
    departed_at timestamp with time zone,
    arrived_at timestamp with time zone,
    handed_over_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    shipment_id bigint,
    assignment_id bigint,
    CONSTRAINT chk_order_assignment_required CHECK ((((status)::text = ANY ((ARRAY['CREATED'::character varying, 'CANCELED'::character varying])::text[])) OR ((vehicle_no IS NOT NULL) AND (shipment_id IS NOT NULL) AND (assignment_id IS NOT NULL)))),
    CONSTRAINT chk_order_status CHECK (((status)::text = ANY ((ARRAY['CREATED'::character varying, 'ASSIGNED'::character varying, 'LOADED'::character varying, 'GATE_OUT'::character varying, 'IN_TRANSIT'::character varying, 'ARRIVED'::character varying, 'HANDED_OVER'::character varying, 'CANCELED'::character varying])::text[])))
);


