    CONSTRAINT chk_trip_event_type CHECK (((event_type)::text = ANY ((ARRAY['GATE_OUT'::character varying, 'DEPART'::character varying, 'TOLL_PASS'::character varying, 'CHECKPOINT_NEAR'::character varying, 'HEIGHT_WARNING'::character varying, 'ROUTE_DEVIATION'::character varying, 'REROUTE'::character varying, 'HUB_ENTER'::character varying, 'HANDOVER'::character varying, 'ORDER_CHANGED'::character varying])::text[])))
