    CONSTRAINT chk_trucks_container_is_semi CHECK ((((vehicle_category)::text IS DISTINCT FROM 'CONTAINER_TRUCK'::text) OR is_semi_trailer)),
    CONSTRAINT chk_trucks_semi_trailer_no CHECK (((NOT is_semi_trailer) OR (trailer_no IS NOT NULL))),
