--
-- Name: v_order_autofill; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_order_autofill AS
 SELECT o.order_id,
    o.order_no,
    o.status,
    o.vehicle_no,
    o.container_no,
    c.iso_size_type_code,
    c.is_high_cube,
    c.max_gross_kg,
    t.terminal_name AS origin_name,
    t.latitude AS origin_lat,
    t.longitude AS origin_lng,
    dest.center_name AS dest_name,
    dest.address AS dest_address,
    dest.latitude AS dest_lat,
    dest.longitude AS dest_lng,
    gl.pass_at AS gate_out_at,
    g.gate_name AS gate_out_name,
    vs.empty_weight_kg,
    vs.max_payload_kg,
    vs.axle_count,
    vs.chassis_height_m,
    ( SELECT min(hr.limit_height_m) AS min
           FROM public.height_restrictions hr
          WHERE (((hr.target_type)::text = 'HUB_ENTRANCE'::text) AND (hr.hub_id = h.hub_id))) AS dest_height_limit_m,
    ( SELECT min(hr.limit_height_m) AS min
           FROM public.height_restrictions hr
          WHERE (((hr.target_type)::text = 'TERMINAL_GATE'::text) AND (hr.terminal_id = t.terminal_id))) AS origin_height_limit_m
   FROM (((((((public.transport_orders o
     JOIN public.containers c ON (((c.container_no)::text = (o.container_no)::text)))
     JOIN public.terminals t ON ((t.terminal_id = o.origin_terminal_id)))
     JOIN public.hubs h ON ((h.hub_id = o.dest_hub_id)))
     JOIN public.logistics_centers dest ON ((dest.center_id = h.center_id)))
     LEFT JOIN public.gate_logs gl ON ((gl.gate_log_id = o.gate_out_log_id)))
     LEFT JOIN public.gates g ON ((g.gate_id = gl.gate_id)))
     LEFT JOIN public.vehicle_specs vs ON (((vs.vehicle_no)::text = (o.vehicle_no)::text)));


--
-- Name: v_scargo_ppt_toll_charges; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_scargo_ppt_toll_charges AS
 SELECT route_code,
    charge_code,
    (start_seq)::integer AS start_seq,
    (end_seq)::integer AS end_seq,
    (amount_won)::integer AS amount_won,
    allocation_owner,
    amount_basis,
    notes
   FROM ( VALUES ('R1_B'::text,'INCHEON_OPEN'::text,'1'::text,'1'::text,'1000'::text,'PUBLIC'::text,'PPT_QUOTED'::text,'인천TG 5종 정상요금'::text), ('R1_B'::text,'DONGSEOUL_GWANGJU'::text,'2'::text,'3'::text,'1600'::text,'PUBLIC'::text,'ESTIMATED_FORMULA'::text,'900 + 9.7×74.4 = 1621.68원, PPT 표기 약1600원'::text), ('R2_INCHEON'::text,'CHEONGGYE'::text,'1'::text,'1'::text,'1200'::text,'PUBLIC'::text,'PPT_QUOTED'::text,'청계TG'::text), ('R2_INCHEON'::text,'MULWANG'::text,'2'::text,'2'::text,'2800'::text,'PRIVATE'::text,'PPT_QUOTED'::text,'물왕TG'::text), ('R2_INCHEON'::text,'GOJAN'::text,'3'::text,'3'::text,'2900'::text,'PRIVATE'::text,'PPT_QUOTED'::text,'고잔TG'::text), ('R2_SEOUL'::text,'PANGYO_EXIT'::text,'1'::text,'1'::text,'1200'::text,'PUBLIC'::text,'PPT_QUOTED'::text,'판교TG 1회차'::text), ('R2_SEOUL'::text,'PANGYO_REENTRY'::text,'2'::text,'2'::text,'1200'::text,'PUBLIC'::text,'PPT_QUOTED'::text,'판교TG 2회차. 재진입 감면 적용 여부 미검증'::text), ('R2_GYEONGGI'::text,'HWASEONG_GWANGJU_GROUP'::text,'2'::text,'3'::text,'5300'::text,'PRIVATE'::text,'PPT_QUOTED'::text,'원톨링 2곳 합산. 개별 지점에 5300원을 중복 적용하지 않음'::text), ('R2_GYEONGGI'::text,'PUBLIC_REMAINDER'::text,'1'::text,'4'::text,'2500'::text,'PUBLIC'::text,'ESTIMATED_DIFFERENCE'::text,'PPT 도공 배분 추정: 7800-5300. 정남 운영 주체 확정 의미 아님'::text)) v(route_code, charge_code, start_seq, end_seq, amount_won, allocation_owner, amount_basis, notes);


--
-- Name: v_scargo_ppt_toll_points; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_scargo_ppt_toll_points AS
 SELECT v.route_code,
    (v.seq)::integer AS seq,
    v.tollgate_code,
    t.tollgate_id,
    t.tollgate_name,
    t.latitude,
    t.longitude,
    t.ppt_ownership_type,
    t.ppt_operator_name,
    v.action,
    v.toll_system,
    v.notes
   FROM (( VALUES ('R1_B'::text,'1'::text,'011'::text,'PAY'::text,'OPEN'::text,'개방식 통행료'::text), ('R1_B'::text,'2'::text,'190'::text,'ENTRY'::text,'CLOSED'::text,'통행권 발권. 미청구는 무료 의미 아님'::text), ('R1_B'::text,'3'::text,'191'::text,'EXIT'::text,'CLOSED'::text,'광주IC 정산'::text), ('R2_INCHEON'::text,'1'::text,'SCARGO-PPT-CHEONGGYE'::text,'PAY'::text,'OPEN'::text,'개방식'::text), ('R2_INCHEON'::text,'2'::text,'SCARGO-PPT-MULWANG'::text,'PAY'::text,'OPEN'::text,'제3경인 요금소'::text), ('R2_INCHEON'::text,'3'::text,'SCARGO-PPT-GOJAN'::text,'PAY'::text,'OPEN'::text,'제3경인 요금소'::text), ('R2_SEOUL'::text,'1'::text,'065'::text,'EXIT'::text,'OPEN'::text,'PPT 개방식 1회차 진출'::text), ('R2_SEOUL'::text,'2'::text,'065'::text,'ENTRY'::text,'OPEN'::text,'PPT 개방식 2회차 재진입'::text), ('R2_GYEONGGI'::text,'1'::text,'192'::text,'ENTRY'::text,'CLOSED'::text,'통행권 발권'::text), ('R2_GYEONGGI'::text,'2'::text,'835'::text,'GANTRY'::text,'ONE_TOLLING'::text,'무정차. 중리와 합산 청구'::text), ('R2_GYEONGGI'::text,'3'::text,'837'::text,'GANTRY'::text,'ONE_TOLLING'::text,'서용인과 합산 5300원. 지점별 배분 미확인'::text), ('R2_GYEONGGI'::text,'4'::text,'672'::text,'EXIT'::text,'CLOSED'::text,'곤지암→정남 정산 구조는 PPT 기준'::text)) v(route_code, seq, tollgate_code, action, toll_system, notes)
     LEFT JOIN public.tollgates t ON (((t.tollgate_code)::text = v.tollgate_code)));


--
-- Name: v_scargo_ppt_toll_routes; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_scargo_ppt_toll_routes AS
 SELECT route_code,
    route_name,
    origin_address,
    destination_address,
    (distance_km)::numeric(8,2) AS distance_km,
    (duration_minutes)::integer AS duration_minutes,
    (expected_total_won)::integer AS expected_total_won,
    (slide_no)::integer AS slide_no,
    amount_basis,
    notes,
    '2026-10-21'::date AS reference_date,
    (5)::smallint AS vehicle_class,
    'scargo_route_toll.pptx'::text AS source_file,
    ( SELECT logistics_centers.center_id
           FROM public.logistics_centers
          WHERE ((logistics_centers.center_code)::text = v.origin_center_code)) AS origin_center_id,
    ( SELECT logistics_centers.center_id
           FROM public.logistics_centers
          WHERE ((logistics_centers.center_code)::text = v.destination_center_code)) AS destination_center_id
   FROM ( VALUES ('R1_B'::text,'인천 월미도 → 곤지암 허브 (B 경로)'::text,'인천광역시 월미로 181'::text,'광주시 초월읍 산수로 642-70'::text,'100.9'::text,NULL::text,'2600'::text,'3'::text,'ESTIMATED'::text,'PPT 1구간 B 경로. 출발지 월미도(내항)는 DB의 항만 거점(인천신항)과 다름. 7장 톨게이트 시연과 같은 폐쇄식 구간(동서울 190 발권 → 경기광주 191 정산)'::text,NULL::text,'HUB-GONJIAM-01'::text), ('R2_INCHEON'::text,'곤지암 허브 → 인천 물류센터'::text,'광주시 초월읍 산수로 642-70'::text,'남동구 논현고잔로 137'::text,'67.9'::text,'74'::text,'6900'::text,'4'::text,'PPT_QUOTED'::text,'PPT 카카오맵 5종 조회값'::text,'HUB-GONJIAM-01'::text,'SCARGO-ICN-185'::text), ('R2_SEOUL'::text,'곤지암 허브 → 서울 물류센터'::text,'광주시 초월읍 산수로 642-70'::text,'서초구 양재대로12길 25'::text,'38.7'::text,'45'::text,'2400'::text,'5'::text,'PPT_QUOTED'::text,'판교TG 진출·회차 후 재진입 각 1회. 회차 면제/할인 미검증'::text,'HUB-GONJIAM-01'::text,'SCARGO-SEL-3264'::text), ('R2_GYEONGGI'::text,'곤지암 허브 → 경기 물류센터'::text,'광주시 초월읍 산수로 642-70'::text,'화성시 효행구 정남면 만년로 697-18'::text,'62.1'::text,'69'::text,'7800'::text,'6'::text,'PPT_QUOTED'::text,'도공/민자 배분 중 2500원은 차감 추정. 운영 분류 검증 필요'::text,'HUB-GONJIAM-01'::text,'SCARGO-GGI-2728'::text)) v(route_code, route_name, origin_address, destination_address, distance_km, duration_minutes, expected_total_won, slide_no, amount_basis, notes, origin_center_code, destination_center_code);


--
-- Name: v_scargo_ppt_toll_totals; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_scargo_ppt_toll_totals AS
 SELECT r.route_code,
    r.route_name,
    r.vehicle_class,
    r.reference_date,
    r.expected_total_won,
    COALESCE(sum(c.amount_won), (0)::bigint) AS calculated_total_won,
    COALESCE(sum(c.amount_won) FILTER (WHERE (c.allocation_owner = 'PUBLIC'::text)), (0)::bigint) AS ppt_public_won,
    COALESCE(sum(c.amount_won) FILTER (WHERE (c.allocation_owner = 'PRIVATE'::text)), (0)::bigint) AS ppt_private_won,
    COALESCE(bool_or((c.amount_basis <> 'PPT_QUOTED'::text)), false) AS has_estimate
   FROM (public.v_scargo_ppt_toll_routes r
     LEFT JOIN public.v_scargo_ppt_toll_charges c USING (route_code))
  GROUP BY r.route_code, r.route_name, r.vehicle_class, r.reference_date, r.expected_total_won;


