--
-- Name: v_toll_points; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_toll_points AS
 SELECT c.point_code,
    c.seq,
    c.point_name,
    c.kind,
    c.retest_max,
    ws.station_id,
    ws.station_code,
    ws.tollgate_id
   FROM (( VALUES ('ENTRY'::text,1,'입장 톨게이트'::text,'TOLLGATE'::text,0,'TOLL-IN-190'::text), ('CK1'::text,2,'검문소 1'::text,'CHECKPOINT'::text,1,'CHECKPOINT-38'::text), ('CK2'::text,3,'검문소 2'::text,'CHECKPOINT'::text,1,'CHECKPOINT-36'::text), ('CK3'::text,4,'검문소 3'::text,'CHECKPOINT'::text,1,'CHECKPOINT-34'::text), ('EXIT'::text,5,'퇴장 톨게이트'::text,'TOLLGATE'::text,0,'TOLL-OUT-191'::text)) c(point_code, seq, point_name, kind, retest_max, station_code)
     JOIN public.weigh_stations ws ON (((ws.station_code)::text = c.station_code)));


--
-- Name: v_toll_gate_log; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_toll_gate_log AS
 SELECT p.passage_id,
    p.detected_at,
    t.tollgate_name,
    ((p.entry_passage_id IS NOT NULL) OR (p.tollgate_id IN ( SELECT v_toll_points.tollgate_id
           FROM public.v_toll_points
          WHERE (v_toll_points.point_code = 'EXIT'::text)))) AS is_exit,
    p.recognized_plate_no,
    p.vehicle_no,
    p.plate_confidence,
    p.plate_crop_url,
    p.recognition_status,
    p.passage_status,
    p.block_reason,
    c.total_weight_kg,
    c.is_violation,
    c.violation_reason,
    c.fine_manwon,
    c.is_reoffense,
    p.fare_won
   FROM ((public.toll_passages p
     JOIN public.tollgates t ON ((t.tollgate_id = p.tollgate_id)))
     LEFT JOIN LATERAL ( SELECT c_1.check_id,
            c_1.vehicle_no,
            c_1.container_no,
            c_1.usage_purpose,
            c_1.empty_weight_kg,
            c_1.total_weight_kg,
            c_1.max_payload_kg,
            c_1.vgm_kg,
            c_1.tire_count,
            c_1.vehicle_axle_count,
            c_1.axle_count,
            c_1.axle1_weight,
            c_1.axle2_weight,
            c_1.axle3_weight,
            c_1.axle4_weight,
            c_1.axle5_weight,
            c_1.axle6_weight,
            c_1.axle7_weight,
            c_1.axle8_weight,
            c_1.axle1_wheel_left,
            c_1.axle1_wheel_right,
            c_1.axle2_wheel_left,
            c_1.axle2_wheel_right,
            c_1.axle3_wheel_left,
            c_1.axle3_wheel_right,
            c_1.axle4_wheel_left,
            c_1.axle4_wheel_right,
            c_1.axle5_wheel_left,
            c_1.axle5_wheel_right,
            c_1.axle6_wheel_left,
            c_1.axle6_wheel_right,
            c_1.axle7_wheel_left,
            c_1.axle7_wheel_right,
            c_1.axle8_wheel_left,
            c_1.axle8_wheel_right,
            c_1.is_violation,
            c_1.violation_reason,
            c_1.retry_count,
            c_1.is_passed,
            c_1.checked_at,
            c_1.shipment_id,
            c_1.assignment_id,
            c_1.station_id,
            c_1.check_type,
            c_1.detection_status,
            c_1.gate_log_id,
            c_1.station_code,
            c_1.trip_passage_id,
            c_1.fine_manwon,
            c_1.is_reoffense
           FROM (public.overload_checks c_1
             JOIN public.weigh_stations w ON ((w.station_id = c_1.station_id)))
          WHERE ((c_1.trip_passage_id = COALESCE(p.entry_passage_id, p.passage_id)) AND (w.tollgate_id = p.tollgate_id))
          ORDER BY c_1.checked_at DESC, c_1.check_id DESC
         LIMIT 1) c ON (true));


--
-- Name: v_toll_trip_current; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_toll_trip_current AS
 SELECT e.passage_id AS trip_id,
    e.vehicle_no,
    e.passed_at AS entered_at,
    e.plate_confidence,
    e.plate_crop_url,
    e.front_image_url,
    x.passage_id AS exit_passage_id,
    x.passed_at AS exited_at,
    lc.check_id AS last_check_id,
    COALESCE(lp.point_code, 'ENTRY'::text) AS last_point,
    COALESCE(lp.point_name, '입장 톨게이트'::text) AS last_point_name,
    COALESCE(lp.seq, 1) AS last_seq,
    lc.total_weight_kg AS last_weight_kg,
    lc.is_violation AS last_violation,
    lc.retry_count AS last_retry,
        CASE
            WHEN ((x.passage_id IS NOT NULL) AND ((x.passage_status)::text = 'PASSED'::text)) THEN 'COMPLETED'::text
            WHEN ((lc.is_passed = false) AND (lc.retry_count >= COALESCE(lp.retest_max, 0))) THEN 'HALTED'::text
            WHEN (lc.is_passed = false) THEN 'RETESTING'::text
            ELSE 'RUNNING'::text
        END AS status,
    COALESCE(f.fine_manwon, (0)::bigint) AS fine_manwon,
    x.fare_won,
    GREATEST(e.passed_at, lc.checked_at, x.passed_at) AS updated_at
   FROM (((((public.toll_passages e
     JOIN public.v_toll_points ep ON (((ep.point_code = 'ENTRY'::text) AND (ep.tollgate_id = e.tollgate_id))))
     LEFT JOIN LATERAL ( SELECT x1.passage_id,
            x1.tollgate_id,
            x1.recognized_plate_no,
            x1.vehicle_no,
            x1.assignment_id,
            x1.check_id,
            x1.recognition_status,
            x1.passage_status,
            x1.block_reason,
            x1.detected_at,
            x1.passed_at,
            x1.created_at,
            x1.plate_confidence,
            x1.front_image_url,
            x1.plate_crop_url,
            x1.entry_passage_id,
            x1.fare_won
           FROM public.toll_passages x1
          WHERE (x1.entry_passage_id = e.passage_id)
          ORDER BY ((x1.passage_status)::text = 'PASSED'::text) DESC, x1.detected_at DESC, x1.passage_id DESC
         LIMIT 1) x ON (true))
     LEFT JOIN LATERAL ( SELECT c.check_id,
            c.vehicle_no,
            c.container_no,
            c.usage_purpose,
            c.empty_weight_kg,
            c.total_weight_kg,
            c.max_payload_kg,
            c.vgm_kg,
            c.tire_count,
            c.vehicle_axle_count,
            c.axle_count,
            c.axle1_weight,
            c.axle2_weight,
            c.axle3_weight,
            c.axle4_weight,
            c.axle5_weight,
            c.axle6_weight,
            c.axle7_weight,
            c.axle8_weight,
            c.axle1_wheel_left,
            c.axle1_wheel_right,
            c.axle2_wheel_left,
            c.axle2_wheel_right,
            c.axle3_wheel_left,
            c.axle3_wheel_right,
            c.axle4_wheel_left,
            c.axle4_wheel_right,
            c.axle5_wheel_left,
            c.axle5_wheel_right,
            c.axle6_wheel_left,
            c.axle6_wheel_right,
            c.axle7_wheel_left,
            c.axle7_wheel_right,
            c.axle8_wheel_left,
            c.axle8_wheel_right,
            c.is_violation,
            c.violation_reason,
            c.retry_count,
            c.is_passed,
            c.checked_at,
            c.shipment_id,
            c.assignment_id,
            c.station_id,
            c.check_type,
            c.detection_status,
            c.gate_log_id,
            c.station_code,
            c.trip_passage_id,
            c.fine_manwon,
            c.is_reoffense
           FROM public.overload_checks c
          WHERE (c.trip_passage_id = e.passage_id)
          ORDER BY c.checked_at DESC, c.check_id DESC
         LIMIT 1) lc ON (true))
     LEFT JOIN public.v_toll_points lp ON ((lp.station_id = lc.station_id)))
     LEFT JOIN LATERAL ( SELECT sum(c.fine_manwon) AS fine_manwon
           FROM public.overload_checks c
          WHERE (c.trip_passage_id = e.passage_id)) f ON (true))
  WHERE ((e.passage_status)::text = 'PASSED'::text);


--
-- Name: vehicle_checklist; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.vehicle_checklist (
    inspection_id bigint NOT NULL,
    vehicle_no character varying(20) NOT NULL,
    inspector_account_id bigint,
    inspection_date date DEFAULT CURRENT_DATE NOT NULL,
    light_status character varying(20) DEFAULT 'PASS'::character varying NOT NULL,
    brake_status character varying(20) DEFAULT 'PASS'::character varying NOT NULL,
    air_brake_status character varying(20) DEFAULT 'PASS'::character varying NOT NULL,
    tire_status character varying(20) DEFAULT 'PASS'::character varying NOT NULL,
    steering_status character varying(20) DEFAULT 'PASS'::character varying NOT NULL,
    cargo_securement_status character varying(20) DEFAULT 'PASS'::character varying NOT NULL,
    engine_oil_status character varying(20) DEFAULT 'PASS'::character varying NOT NULL,
    seatbelt_status character varying(20) DEFAULT 'PASS'::character varying NOT NULL,
    fire_extinguisher_status character varying(20) DEFAULT 'PASS'::character varying NOT NULL,
    safety_triangle_status character varying(20) DEFAULT 'PASS'::character varying NOT NULL,
    overall_status character varying(20) DEFAULT 'PASS'::character varying NOT NULL,
    memo text,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_air_brake_status CHECK (((air_brake_status)::text = ANY ((ARRAY['PASS'::character varying, 'FAIL'::character varying, 'NA'::character varying])::text[]))),
    CONSTRAINT chk_brake_chk_status CHECK (((brake_status)::text = ANY ((ARRAY['PASS'::character varying, 'FAIL'::character varying, 'NA'::character varying])::text[]))),
    CONSTRAINT chk_cargo_chk_status CHECK (((cargo_securement_status)::text = ANY ((ARRAY['PASS'::character varying, 'FAIL'::character varying, 'NA'::character varying])::text[]))),
    CONSTRAINT chk_fire_ext_status CHECK (((fire_extinguisher_status)::text = ANY ((ARRAY['PASS'::character varying, 'FAIL'::character varying, 'NA'::character varying])::text[]))),
    CONSTRAINT chk_light_chk_status CHECK (((light_status)::text = ANY ((ARRAY['PASS'::character varying, 'FAIL'::character varying, 'NA'::character varying])::text[]))),
    CONSTRAINT chk_oil_chk_status CHECK (((engine_oil_status)::text = ANY ((ARRAY['PASS'::character varying, 'FAIL'::character varying, 'NA'::character varying])::text[]))),
    CONSTRAINT chk_overall_status CHECK (((overall_status)::text = ANY ((ARRAY['PASS'::character varying, 'FAIL'::character varying])::text[]))),
    CONSTRAINT chk_safety_tri_status CHECK (((safety_triangle_status)::text = ANY ((ARRAY['PASS'::character varying, 'FAIL'::character varying, 'NA'::character varying])::text[]))),
    CONSTRAINT chk_seatbelt_status CHECK (((seatbelt_status)::text = ANY ((ARRAY['PASS'::character varying, 'FAIL'::character varying, 'NA'::character varying])::text[]))),
    CONSTRAINT chk_steering_status CHECK (((steering_status)::text = ANY ((ARRAY['PASS'::character varying, 'FAIL'::character varying, 'NA'::character varying])::text[]))),
    CONSTRAINT chk_tire_chk_status CHECK (((tire_status)::text = ANY ((ARRAY['PASS'::character varying, 'FAIL'::character varying, 'NA'::character varying])::text[])))
);


